  "inlineSchema": "// Worker Management ERP - Kurti Manufacturing Factory\n// Prisma Supabase PostgreSQL Schema Definition\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\nenum UserRole {\n  OWNER\n  MANAGER\n  CUTTING_MASTER\n}\n\nenum UserStatus {\n  ACTIVE\n  INACTIVE\n}\n\nenum EmployeeStatus {\n  ACTIVE\n  INACTIVE\n}\n\nenum JobCardPriority {\n  NORMAL\n  HIGH\n  URGENT\n}\n\nenum JobCardStatus {\n  CREATED\n  READY_FOR_CUTTING\n  CUTTING_IN_PROGRESS\n  CUTTING_COMPLETED\n}\n\nenum CuttingStatus {\n  PENDING\n  IN_PROGRESS\n  COMPLETED\n}\n\nenum BundleStatus {\n  READY_FOR_ASSIGNMENT\n  IN_ASSIGNMENT\n  COMPLETED\n}\n\nenum AssignmentStatus {\n  ASSIGNED\n  IN_PROGRESS\n  COMPLETED\n  SALARY_PENDING\n  CANCELLED\n}\n\nmodel User {\n  id            String     @id @default(uuid())\n  full_name     String\n  email         String     @unique\n  password_hash String\n  role          UserRole   @default(CUTTING_MASTER)\n  status        UserStatus @default(ACTIVE)\n  last_login    DateTime?\n  created_at    DateTime   @default(now())\n  updated_at    DateTime   @updatedAt\n\n  @@map(\"users\")\n}\n\nmodel Employee {\n  id            String         @id @default(uuid())\n  employee_code String         @unique\n  employee_name String\n  phone         String         @unique\n  joining_date  DateTime\n  status        EmployeeStatus @default(ACTIVE)\n  notes         String?\n  is_deleted    Boolean        @default(false)\n  deleted_at    DateTime?\n  deleted_by    String?\n  created_at    DateTime       @default(now())\n  updated_at    DateTime       @updatedAt\n\n  assignments Assignment[]\n  advances    EmployeeAdvance[]\n  payments    EmployeePayment[]\n\n  @@index([status, is_deleted])\n  @@map(\"employees\")\n}\n\nmodel JobCard {\n  id              String          @id @default(uuid())\n  job_card_number String          @unique\n  design_code     String\n  components      String          @default(\"Top,Pant\")\n  stitching_rate  Float           @default(110.0) // Stitching rate per finished piece\n  total_quantity  Int\n  priority        JobCardPriority @default(NORMAL)\n  due_date        DateTime\n  status          JobCardStatus   @default(CREATED)\n  remarks         String?\n  created_by      String?\n  is_deleted      Boolean         @default(false)\n  deleted_at      DateTime?\n  deleted_by      String?\n  created_at      DateTime        @default(now())\n  updated_at      DateTime        @updatedAt\n\n  items            JobCardItem[]\n  cutting_progress CuttingProgress[]\n  bundles          Bundle[]\n\n  @@index([status, is_deleted])\n  @@index([due_date])\n  @@map(\"job_cards\")\n}\n\nmodel JobCardItem {\n  id          String   @id @default(uuid())\n  job_card_id String\n  color       String // Red, Blue, Green, Black, etc.\n  size        String // Dynamic size name\n  quantity    Int\n  created_at  DateTime @default(now())\n\n  job_card JobCard @relation(fields: [job_card_id], references: [id], onDelete: Cascade)\n\n  @@index([job_card_id])\n  @@map(\"job_card_items\")\n}\n\nmodel CuttingProgress {\n  id           String        @id @default(uuid())\n  job_card_id  String\n  component    String // Top, Pant, Top Aster, Pant Aster\n  status       CuttingStatus @default(PENDING)\n  completed_at DateTime?\n  completed_by String?\n  created_at   DateTime      @default(now())\n  updated_at   DateTime      @updatedAt\n\n  job_card JobCard @relation(fields: [job_card_id], references: [id], onDelete: Cascade)\n\n  @@unique([job_card_id, component])\n  @@index([job_card_id, status])\n  @@map(\"cutting_progress\")\n}\n\nmodel Bundle {\n  id             String       @id @default(uuid())\n  bundle_number  String       @unique // e.g. 2001-RD-M\n  job_card_id    String\n  color          String // Red, Blue, etc.\n  size           String // Dynamic size name\n  total_sets     Int\n  assigned_sets  Int          @default(0)\n  completed_sets Int          @default(0)\n  status         BundleStatus @default(READY_FOR_ASSIGNMENT)\n  is_deleted     Boolean      @default(false)\n  deleted_at     DateTime?\n  deleted_by     String?\n  created_at     DateTime     @default(now())\n  updated_at     DateTime     @updatedAt\n\n  job_card    JobCard      @relation(fields: [job_card_id], references: [id], onDelete: Cascade)\n  assignments Assignment[]\n\n  @@index([job_card_id, status, is_deleted])\n  @@map(\"bundles\")\n}\n\nmodel Assignment {\n  id             String           @id @default(uuid())\n  bundle_id      String\n  employee_id    String\n  assigned_sets  Int\n  completed_sets Int              @default(0)\n  stitching_rate Float // Snapshot of JobCard.stitching_rate\n  status         AssignmentStatus @default(ASSIGNED)\n  assigned_by    String\n  remarks        String?\n  is_deleted     Boolean          @default(false)\n  deleted_at     DateTime?\n  deleted_by     String?\n  created_at     DateTime         @default(now())\n  updated_at     DateTime         @updatedAt\n\n  bundle   Bundle              @relation(fields: [bundle_id], references: [id], onDelete: Cascade)\n  employee Employee            @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n  history  AssignmentHistory[]\n\n  @@index([bundle_id, employee_id, status, is_deleted])\n  @@map(\"assignments\")\n}\n\nmodel AssignmentHistory {\n  id            String   @id @default(uuid())\n  assignment_id String\n  action        String // ASSIGNED, PROGRESS_UPDATED, COMPLETED, CANCELLED\n  previous_sets Int?\n  new_sets      Int?\n  performed_by  String\n  notes         String?\n  created_at    DateTime @default(now())\n\n  assignment Assignment @relation(fields: [assignment_id], references: [id], onDelete: Cascade)\n\n  @@index([assignment_id])\n  @@map(\"assignment_history\")\n}\n\nmodel EmployeeAdvance {\n  id           String   @id @default(uuid())\n  employee_id  String\n  amount       Float\n  reason       String?\n  advance_date DateTime @default(now())\n  created_by   String\n  created_at   DateTime @default(now())\n\n  employee Employee @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n\n  @@index([employee_id])\n  @@map(\"employee_advances\")\n}\n\nmodel EmployeePayment {\n  id           String   @id @default(uuid())\n  employee_id  String\n  amount       Float\n  payment_mode String   @default(\"CASH\")\n  reference_no String?\n  payment_date DateTime @default(now())\n  created_by   String\n  created_at   DateTime @default(now())\n\n  employee Employee @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n\n  @@index([employee_id])\n  @@map(\"employee_payments\")\n}\n\nmodel Notification {\n  id             String   @id @default(uuid())\n  title          String\n  message        String\n  type           String\n  priority       String   @default(\"MEDIUM\") // CRITICAL, HIGH, MEDIUM, LOW\n  reference_type String? // JOB_CARD, BUNDLE, EMPLOYEE, SALARY\n  reference_id   String?\n  user_role      String   @default(\"ALL\") // ALL, OWNER, MANAGER, CUTTING_MASTER\n  is_read        Boolean  @default(false)\n  created_at     DateTime @default(now())\n  updated_at     DateTime @updatedAt\n\n  @@index([user_role, is_read])\n  @@map(\"notifications\")\n}\n\nmodel SystemSetting {\n  id         String   @id @default(uuid())\n  key        String   @unique\n  value      String\n  category   String   @default(\"GENERAL\") // COMPANY, FACTORY, EMPLOYEE, JOB_CARD, BUNDLE, SALARY, NOTIFICATION, ROLE\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  @@map(\"system_settings\")\n}\n\nmodel GarmentSize {\n  id            String   @id @default(uuid())\n  size_name     String   @unique\n  display_order Int      @default(0)\n  is_active     Boolean  @default(true)\n  created_at    DateTime @default(now())\n  updated_at    DateTime @updatedAt\n\n  @@index([is_active, display_order])\n  @@map(\"garment_sizes\")\n}\n",
